#include "oracle_chain.hpp"
#include "native_fx.hpp"
#include <sstream>
#include <iomanip>
namespace vamp {
int configureOracleEffect(Plugin&fx,const AssistantStep&step,Json*controls){
    if(controls)*controls=Json::array();
    if(step.kind<0||step.kind>=46)throw std::runtime_error("Invalid Oracle role");for(auto&s:step.settings)if(s.first<0||s.first>=(int)nativeSpecs()[step.kind].parameters.size()||!std::isfinite(s.second))throw std::runtime_error("Invalid Oracle parameter");
    if(fx.native){for(auto&setting:step.settings){if(setting.first<0||setting.first>=(int)fx.native->spec().parameters.size())throw std::runtime_error("Invalid Oracle parameter");auto&p=fx.native->spec().parameters[setting.first];fx.native->set(setting.first,p.normalized(setting.second));if(controls)controls->push_back({{"suggested",p.name},{"value",setting.second},{"mapped",true},{"parameter",p.name},{"unit",p.unit},{"minimum",p.low},{"maximum",p.high},{"normalized",p.normalized(setting.second)}});}return(int)step.settings.size();}
    int mapped=0;auto parameters=fx.parameters();for(auto&setting:step.settings){std::vector<std::string>names;std::string unit;
        if(step.kind==3||step.kind==8){switch(setting.first){case 0:names={"threshold","thresh"};unit="db";break;case 1:names={"ratio"};unit="ratio";break;case 2:names={"attack","attacktime"};unit="ms";break;case 3:names={"release","releasetime"};unit="ms";break;case 4:names={"makeup","makeupgain"};unit="db";break;}}
        if(step.kind==27&&setting.first==0){names={"gain","trim","outputgain"};unit="db";}
        if(step.kind==31&&setting.first==1){names={"ceiling","outputceiling"};unit="db";}
        if(step.kind==9&&setting.first==1){names={"threshold","thresh"};unit="db";}
        auto&definition=nativeSpecs()[step.kind].parameters[setting.first];auto canonical=oracleKey(definition.name);if(unit.empty())unit=definition.unit;
        if(canonical=="makeup")names.insert(names.end(),{"makeupgain","compensationgain"});
        if(canonical.rfind("band",0)==0&&canonical.size()>5){size_t at=4;while(at<canonical.size()&&std::isdigit((unsigned char)canonical[at]))at++;auto number=canonical.substr(4,at-4),control=canonical.substr(at);for(auto field:{control,control=="frequency"?std::string("freq"):control}){names.push_back("band"+number+field);names.push_back("b"+number+field);names.push_back(field+number);}}
        if(canonical.find("type")==std::string::npos&&canonical!="externalsidechain"){names.push_back(canonical);if(canonical=="frequency")names.push_back("freq");if(canonical=="mix"){names.push_back("wet");names.push_back("wetdry");names.push_back("drywet");}if(canonical=="highpass"){names.insert(names.end(),{"highpassfrequency","highpassfreq","hpfrequency","lowcut","lowcutfrequency"});}if(canonical=="lowpass"){names.insert(names.end(),{"lowpassfrequency","lowpassfreq","lpfrequency","highcut","highcutfrequency"});}}
        if(unit=="ratio")unit="";
        Json match={{"suggested",definition.name},{"value",setting.second},{"unit",definition.unit},{"mapped",false}};for(auto&p:parameters){auto name=oracleControlKey(p.name,p.unit);if(std::find(names.begin(),names.end(),name)==names.end())continue;if(fx.setParameterPhysical(p.id,setting.second,unit)){mapped++;double n=fx.parameterValue(p.id);match.update({{"mapped",true},{"parameter",p.name},{"id",p.id},{"unit",p.unit},{"normalized",n},{"readout",fx.parameterDisplay(p.id,n)},{"minimum",fx.parameterDisplay(p.id,0)},{"maximum",fx.parameterDisplay(p.id,1)}});}break;}if(controls)controls->push_back(std::move(match));
    }return mapped;
}
std::shared_ptr<Plugin>loadOracleEffect(const AssistantStep&step,double rate,int*mapped,Json*controls){
    if(step.kind<0||step.kind>=46)throw std::runtime_error("Invalid Oracle effect role");auto plug=std::make_shared<Plugin>();std::string error;fs::path path=step.path.empty()?fs::path(L"@vamp")/(wide(nativeSpecs()[step.kind].id)+L".vampfx"):fs::path(wide(step.path));if(!plug->load(path,rate,error))throw std::runtime_error(error);if(plug->instrument())throw std::runtime_error("Oracle needs audio effects, not instruments");int count=configureOracleEffect(*plug,step,controls);if(!plug->prepare(rate))throw std::runtime_error("Oracle effect could not prepare processing");std::array<float,64>l{},r{};plug->process(l.data(),r.data(),64,nullptr,0,0,120,false);if(mapped)*mapped=count;return plug;
}
OraclePreparedChain buildOracleChain(const AssistantPlan&plan,double rate,const AssistantCapture*capture,const std::function<void(size_t,size_t)>&progress,double tempo,double beat){
    if(!std::isfinite(tempo)||tempo<=0)tempo=120;if(!std::isfinite(beat))beat=0;
    OraclePreparedChain result;std::vector<float>l,r;double sourceRms=plan.analysis.rms;bool measured=capture&&plan.analyzed&&capture->written>=capture->targetFrames.load()&&(capture->state.load()==0||capture->state.load()==3);
    if(measured){size_t count=std::min(capture->written,(size_t)(capture->rate*2)),first=0;auto energy=[&](size_t i){return(double)capture->left[i]*capture->left[i]+(double)capture->right[i]*capture->right[i];};double power=0;for(size_t i=0;i<count;i++)power+=energy(i);double distance=1e100;size_t step=std::max<size_t>(1,(size_t)(capture->rate*.25)),previous=0;for(size_t start=0;;){for(size_t i=previous;i<start;i++){power-=energy(i);power+=energy(i+count);}double db=10*std::log10(std::max(1e-24,power/(2*std::max<size_t>(1,count))));double error=std::abs(db-plan.analysis.rms);if(db>-90&&error<distance){distance=error;first=start;}if(start+count>=capture->written)break;previous=start;start=std::min(capture->written-count,start+step);}if(distance==1e100)measured=false;l.assign(capture->left.begin()+first,capture->left.begin()+first+count);r.assign(capture->right.begin()+first,capture->right.begin()+first+count);if(std::abs(rate-capture->rate)>.5){size_t n=(size_t)(count*rate/capture->rate);std::vector<float>a(n),b(n);for(size_t i=0;i<n;i++){double at=i*capture->rate/rate;size_t index=std::min(count-1,(size_t)at),next=std::min(count-1,index+1);float fraction=(float)(at-index);a[i]=l[index]+(l[next]-l[index])*fraction;b[i]=r[index]+(r[next]-r[index])*fraction;}l.swap(a);r.swap(b);}}
    auto rms=[](const std::vector<float>&a,const std::vector<float>&b){double power=0;for(size_t i=0;i<a.size();i++)power+=(double)a[i]*a[i]+(double)b[i]*b[i];return 10*std::log10(std::max(1e-24,power/(2*std::max<size_t>(1,a.size()))));};
    if(measured)sourceRms=rms(l,r);
    for(size_t i=0;i<plan.steps.size();i++){if(progress)progress(i,plan.steps.size());auto step=plan.steps[i];double input=measured?rms(l,r):-120;
        // Calibrate thresholds against the output of the preceding effects, not the original input.
        if(measured){double delta=input-sourceRms;for(auto&setting:step.settings){if((step.kind==3||step.kind==8)&&setting.first==0)setting.second=clamp(setting.second+delta,-80,0);if((step.kind==9||step.kind==37)&&setting.first==1)setting.second=clamp(setting.second+delta,-60,0);if(step.kind==27&&setting.first==0&&i+1==plan.steps.size()){auto&preset=assistantPresets()[plan.preset];setting.second=clamp(preset.target-input,-12,3)*plan.strength*.01;}if(step.kind==31&&setting.first==0){auto&preset=assistantPresets()[plan.preset];setting.second=clamp(preset.target-input,0,6)*plan.strength*.01;}}}
        int mapped=0;Json controls;auto effect=loadOracleEffect(step,rate,&mapped,&controls);double output=-120,peak=-120;
        if(measured){size_t count=l.size();int latency=effect->latency();l.resize(count+latency);r.resize(count+latency);for(size_t at=0;at<l.size();at+=MaxBlock){int n=(int)std::min<size_t>(MaxBlock,l.size()-at);effect->process(l.data()+at,r.data()+at,n,nullptr,0,beat+at/rate*tempo/60,tempo,true);}
            if(latency){std::move(l.begin()+latency,l.end(),l.begin());std::move(r.begin()+latency,r.end(),r.begin());}l.resize(count);r.resize(count);double maximum=0;for(size_t n=0;n<count;n++){if(!std::isfinite(l[n])||!std::isfinite(r[n]))throw std::runtime_error("Oracle rejected a chain with invalid audio");maximum=std::max({maximum,std::abs((double)l[n]),std::abs((double)r[n])});}peak=20*std::log10(std::max(1e-12,maximum));output=rms(l,r);if(peak>24)throw std::runtime_error("Oracle rejected excessive gain in the proposed chain");if(!effect->prepare(rate))throw std::runtime_error("Oracle could not reset an effect after calibration");}
        result.report.push_back({{"name",effect->info.name},{"role",step.kind},{"mapped",mapped},{"suggested",step.settings.size()},{"measured",measured},{"input_rms",input},{"output_rms",output},{"peak_dbfs",peak},{"controls",controls}});result.stages.push_back({step,effect,mapped,input,output,peak});
    }result.calibrated=measured;if(progress)progress(plan.steps.size(),plan.steps.size());return result;
}
}
